private def signedUnits (a : word64) : Int :=
  let v : Int := units64 (code64 a)
  if neg64 a then -v else v
private def roundRatio (m : Rounding) (neg : Bool) (num den : Nat) :=
  round64 m neg (fun t => compare (2*num) (t*den))
private def addSub64 (sub : Bool) (m : Rounding) (a b : word64) : word64 :=
  let x := code64 a
  let y := code64 b
  let sa := neg64 a
  let sb := neg64 b != sub
  let nan := fun _ : Unit => (quiet64 (if sub then 2 else 1) m [a,b]).val
  if x > infCode ∨ y > infCode then nan ()
  else if x = infCode ∧ y = infCode ∧ sa ≠ sb then nan ()
  else if x = infCode then a else if y = infCode then pack64 sb y
  else
    let r := signedUnits a + (if sub then -(signedUnits b) else signedUnits b)
    let neg := if r = 0 then (if x = 0 ∧ y = 0 ∧ sa = sb then sa else decide (m = .roundTowardNegative)) else decide (r < 0)
    roundRatio m neg r.natAbs 1
def fp64_add := addSub64 false
